  if (!wp) {
    if (sc === 'tau' && t < KN.m1T0) callouts(K, t, 'case');
    if (sc === 'tau' && t >= KN.stackT1 && t < KN.prCut) { callouts(K, t, 'side'); pin(K, t, 'bar', PINS.bar, KN.planeOut - 0.2); }
    if (sc === 'pr') { callouts(K, t, 'pr'); callouts(K, t, 'prB'); }
    if (sc === 'min') { callouts(K, t, 'min'); pin(K, t, 'pin27', PINS.pin27, KN.tauCut - 0.4); }
  }

  // COUNT: the pair (each count line before its ratio) and the paper's own sentence
  const lad = [['ONE TRY · ' + P.passed + ' OF ' + P.tries + ' TRIES', pc1(P.pass1), KN.lad1, KN.ladXL, 'ink'], ['EVERY TRY · ' + P.n4 + ' OF ' + P.tasks + ' TASKS', pc1(P.pass4), KN.lad4, KN.ladXR, 'accent']];
