    L.forEach((s, i) => rtx(K, t, 'mo.h' + i, 'labels', xr, KN.monY + i * KN.honestSize * 1.2, s, { at: KN.honestIn, out: KN.qOut, i: i + 1, n, fam: 'disp', size: KN.honestSize, fill: 'accent', role: 'must-read' }));
