      LOOK = M.setup(p, K.BRAND, F.level, { bloomGain: KN.lookBloom, grainSigma: KN.lookGrain, rim: KN.lookRim, shadowA: KN.lookShadow, pool: KN.lookPool, seed: KN.seedLit });
